/bin/bash -lc "cat > src/styles.css <<'EOF'
*, *::before, *::after { box-sizing: border-box; }
.g-root {
  --g-text-display-4-font-size: 76px;
  --g-text-display-4-line-height: 82px;
  --g-text-display-font-weight: 600;
  --g-color-base-brand: var(--g-color-base-positive-heavy);
  --g-color-base-brand-hover: var(--g-color-base-positive-heavy-hover);
  --g-color-base-selection: var(--g-color-base-positive-light);
  --g-color-base-selection-hover: var(--g-color-base-positive-light-hover);
  --g-color-line-brand: var(--g-color-line-positive);
  --g-color-text-brand: var(--g-color-text-positive-heavy);
  --g-color-text-brand-contrast: var(--g-color-text-light-primary);
  --g-color-text-link: var(--g-color-text-positive-heavy);
  --g-color-text-link-hover: var(--g-color-text-positive);
}
body { margin: 0; -webkit-font-smoothing: antialiased; }
.landing {
  --tempo-green: color-mix(in srgb, var(--g-color-text-positive-heavy) 76%, var(--g-color-text-primary));
  --pc-border-radius: var(--g-border-radius-xl);
  min-height: 100vh;
  padding-bottom: calc(var(--g-spacing-10) * 1.5);
  background: color-mix(in srgb, var(--g-color-base-background) 97%, var(--g-color-base-positive-heavy));
}
.hero { padding-top: var(--g-spacing-9); padding-bottom: calc(var(--g-spacing-10) * 1.6); }
.wordmark { max-width: 1120px; margin: 0 auto; padding: 0 var(--g-spacing-8); letter-spacing: -1.6px; }
.wordmark .g-text { font-weight: 750; }
.wordmark-dot { color: var(--tempo-green); }
.hero-block { margin-top: calc(var(--g-spacing-10) * 1.4); }
.hero-inner { width: 100%; max-width: 100%; }
.eyebrow {
  display: inline-flex; align-items: center; gap: var(--g-spacing-2);
  padding: var(--g-spacing-2) var(--g-spacing-4);
  border: 1px solid var(--g-color-line-positive);
  border-radius: var(--g-border-radius-xl);
  background: var(--g-color-base-positive-light); color: var(--tempo-green);
}
.status-dot {
  width: var(--g-spacing-2); height: var(--g-spacing-2); flex-shrink: 0;
  border-radius: var(--g-border-radius-xl); background: var(--g-color-text-positive);
}
.hero-title { display: block; margin-top: var(--g-spacing-6); letter-spacing: -3.5px; }
.hero-accent { color: var(--tempo-green); }
.hero-description { max-width: 620px; margin: var(--g-spacing-6) auto 0; color: var(--g-color-text-secondary); text-wrap: pretty; }
.hero-note { margin: var(--g-spacing-5) 0 0; color: var(--g-color-text-hint); }
.features { max-width: 1056px; margin-inline: auto; }
.feature-card {
  display: flex; flex-direction: column; min-height: 264px; height: 100%;
  padding: var(--g-spacing-7); border: 1px solid var(--g-color-line-generic);
  border-radius: var(--g-border-radius-xl); background: var(--g-color-base-background);
}
.feature-number { color: var(--tempo-green); font-variant-numeric: tabular-nums; font-weight: 500; margin-bottom: var(--g-spacing-6); }
.feature-title { margin: 0 0 var(--g-spacing-3); letter-spacing: -0.45px; }
.feature-description { margin: 0 0 var(--g-spacing-6); color: var(--g-color-text-secondary); line-height: 1.6; text-wrap: pretty; }
.feature-label { margin-top: auto; color: var(--g-color-text-hint); letter-spacing: 1px; font-size: var(--g-text-caption-1-font-size); }
.cta {
  display: flex; align-items: center; justify-content: space-between; gap: var(--g-spacing-8);
  max-width: 1056px; margin: var(--g-spacing-9) auto 0; padding: calc(var(--g-spacing-10) * 1.2);
  border-radius: var(--g-border-radius-xl);
  background: color-mix(in srgb, var(--g-color-text-primary) 75%, var(--g-color-base-positive-heavy));
  color: var(--g-color-text-light-primary);
}
.cta-copy { flex: 1; min-width: 0; }
.cta-eyebrow { margin: 0 0 var(--g-spacing-4); font-size: var(--g-text-caption-1-font-size); letter-spacing: 1.3px; color: var(--g-color-text-light-secondary); }
.cta-title { margin: 0; letter-spacing: -1.1px; }
.cta-description { margin: var(--g-spacing-3) 0 0; color: var(--g-color-text-light-secondary); }
.cta-action { display: flex; flex-direction: column; align-items: center; gap: var(--g-spacing-3); flex-shrink: 0; }
.start-button { --g-button-border-radius: var(--g-border-radius-m); --g-button-text-color: var(--g-color-text-dark-primary); font-weight: 600; min-width: 224px; }
.button-arrow { display: inline-block; margin-left: var(--g-spacing-5); font-size: var(--g-text-body-3-font-size); }
.cta-hint { color: var(--g-color-text-light-secondary); }
.timer { font-variant-numeric: tabular-nums; color: var(--g-color-text-light-primary); }
@media (min-width: 1600px) {
  .hero { padding-top: var(--g-spacing-10); padding-bottom: calc(var(--g-spacing-10) * 2); }
  .hero-block { margin-top: calc(var(--g-spacing-10) * 2); }
}
@media (max-width: 1000px) {
  .cta { padding: var(--g-spacing-8); }
  .feature-card { padding: var(--g-spacing-6); }
  .feature-title { min-height: 52px; }
}
@media (max-width: 768px) {
  .g-root { --g-text-display-4-font-size: 56px; --g-text-display-4-line-height: 62px; }
  .hero { padding-top: var(--g-spacing-6); padding-bottom: var(--g-spacing-9); }
  .hero-block { margin-top: var(--g-spacing-10); }
  .hero-title { letter-spacing: -2.4px; }
  .wordmark { padding-inline: var(--g-spacing-5); }
  .feature-card, .feature-title { min-height: 0; }
  .feature-number { margin-bottom: var(--g-spacing-4); }
  .cta { flex-direction: column; align-items: flex-start; gap: var(--g-spacing-7); margin-top: var(--g-spacing-6); }
  .cta-action { align-items: flex-start; }
}
@media (max-width: 450px) {
  .g-root { --g-text-display-4-font-size: 42px; --g-text-display-4-line-height: 48px; }
  .hero-title { letter-spacing: -1.8px; }
  .hero-description { font-size: var(--g-text-body-2-font-size); line-height: var(--g-text-body-2-line-height); }
  .desktop-break { display: none; }
  .hero-note { max-width: 250px; margin-inline: auto; }
  .cta { padding: var(--g-spacing-6); }
  .cta-title { font-size: var(--g-text-header-1-font-size); line-height: var(--g-text-header-1-line-height); letter-spacing: -0.6px; }
  .cta-description { max-width: 260px; }
}
EOF
npm run build"
